import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

import javax.xml.XMLConstants; // Important for XMLConstants.FEATURE_SECURE_PROCESSING
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

public class SecureXmlParser {

    /**
     * Parses an XML string using a secure DocumentBuilderFactory configuration,
     * preventing XXE attacks.
     *
     * @param xmlInput The XML string to parse, potentially untrusted.
     */
    public static void parseXml(String xmlInput) {
        System.out.println("--- Attempting to parse XML with SECURE configuration ---");
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

            // FIX: Disable DTDs and external entities to prevent XXE.
            // These features block the parser from processing external entities and DTDs,
            // which are the primary vectors for XXE attacks.
            // It's recommended to set ALL these features as different XML processors
            // might interpret them slightly differently, or some features might not be
            // supported, but others will act as a fallback.
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // "http://apache.org/xml/features/disallow-doctype-decl" is specific to Apache Xerces
            // (the default XML processor in many Java environments), but highly effective.
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setXIncludeAware(false);         // Disable XInclude processing
            factory.setExpandEntityReferences(false); // Prevent expanding entity references

            // If you absolutely need to process DTDs for valid documents but want to control external entities,
            // you could set a custom EntityResolver that blocks or sanitizes requests.
            // For general untrusted input, it's best to disable DTD processing entirely.

            DocumentBuilder builder = factory.newDocumentBuilder();

            try (InputStream is = new ByteArrayInputStream(xmlInput.getBytes(StandardCharsets.UTF_8))) {
                Document doc = builder.parse(is);

                NodeList dataNodes = doc.getElementsByTagName("data");
                if (dataNodes.getLength() > 0) {
                    System.out.println("Parsed data content: " + dataNodes.item(0).getTextContent().trim());
                } else {
                    System.out.println("No 'data' element found or processed.");
                }
            }
        } catch (ParserConfigurationException | SAXException | IOException e) {
            System.err.println("Error parsing XML (secure config): " + e.getClass().getSimpleName() + ": " + e.getMessage());
            // For malicious XXE attempts, a SAXException is typically thrown (e.g., "DOCTYPE is disallowed"),
            // indicating that the attack was successfully prevented. This is the desired behavior for untrusted XML.
        }
        System.out.println("------------------------------------------------------------\n");
    }

    public static void main(String[] args) {
        // Example of a malicious XML payload attempting to read /etc/passwd.
        String maliciousXml = "<?xml version=\"1.0\"?>\n" +
                              "<!DOCTYPE foo [\n" +
                              "  <!ENTITY xxe SYSTEM \"file:///etc/passwd\">\n" +
                              "]>\n" +
                              "<data>This is confidential: &xxe;</data>";

